import SwiftUI

/// The actions a list's row or a view's record offers: running an
/// operation after its confirmation, with the reason it asks for.
public enum Actions {
    /// The refusal a status answers, or the page's default.
    public static func refusal(_ failed: [FailureSchema], _ status: Int) -> FailureSchema? {
        failed.first { $0.status == status } ?? failed.first { $0.status == nil }
    }

    /// Whether a permission is held by the session read, and so whether an
    /// action is offered.
    @MainActor
    public static func holds(_ permission: String) -> Bool {
        guard let session = SessionStore.shared.current else {
            return false
        }
        return Access.decide(permission: permission, session: session) == .allowed
    }

    /// Whether an action is offered on a record: its permission held, and its rule holding.
    @MainActor
    public static func offered(_ action: RowActionSchema, _ record: Fields) -> Bool {
        holds(action.permission) && (action.when.map { Rules.evaluate($0, record) == .bool(true) } ?? true)
    }

    /// The path's parameters each from a field of the record, by the names the action maps them from.
    public static func parameters(_ action: RowActionSchema, _ record: Fields) -> [String: String] {
        var out: [String: String] = [:]
        for name in Service.parameterNames(action.path ?? "") {
            out[name] = record[action.parameters?[name] ?? name]?.text ?? ""
        }
        return out
    }

    /// The route an action that opens a page leads to, its parameters each from a field of the record.
    public static func route(_ action: RowActionSchema, _ record: Fields, _ routes: [String: Routes.Make]) -> Route? {
        guard let navigate = action.navigate, let make = routes[navigate] else {
            return nil
        }
        var parameters: [String: String] = [:]
        for (name, from) in action.with ?? [:] {
            parameters[name] = record[from]?.text ?? ""
        }
        return make(parameters)
    }

    /// Runs an action on a record: its path's parameters each from a field of
    /// the record, and the reason, when it asks for one, as the property of the
    /// body it names. It answers nil on a success, or the message of the
    /// refusal.
    @MainActor
    public static func run(_ action: RowActionSchema, _ record: Fields, reason: String, _ texts: Texts) async -> String? {
        var body: JSON?
        if let asked = action.reason {
            body = .object([asked.property: .string(reason.trimmingCharacters(in: .whitespacesAndNewlines))])
        }
        do {
            let answer = try await Service.send(action.method ?? "POST", action.path ?? "", parameters: parameters(action, record), body: body)
            if answer.ok {
                return nil
            }
            return say(texts, refusal(action.failed ?? [], answer.status)?.message ?? "screens.failed")
        } catch {
            return say(texts, "screens.failed")
        }
    }
}

/// An action waiting for its confirmation, on a record.
public struct Confirming: Equatable {
    public var action: RowActionSchema
    public var record: Fields

    public static func == (a: Confirming, b: Confirming) -> Bool {
        a.action.label == b.action.label && a.record == b.record
    }
}

/// The question an action asks before it runs, in a confirmation dialog,
/// with the reason it requires typed in; it is not confirmed while the
/// reason is empty.
struct ConfirmDialog: ViewModifier {
    @Binding var confirming: Confirming?
    @Binding var reason: String
    let texts: Texts
    let running: Bool
    let confirm: (Confirming) -> Void

    var missing: Bool { confirming?.action.reason != nil && reason.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }

    func body(content: Content) -> some View {
        content.sheet(item: Binding(get: { confirming.map(Item.init) }, set: { if $0 == nil { confirming = nil } })) { item in
            NavigationStack {
                Form {
                    if let asked = item.confirming.action.reason {
                        Section {
                            TextField(say(texts, asked.label), text: $reason, axis: .vertical)
                        } footer: {
                            Text(say(texts, "screens.reason"))
                        }
                    }
                    Button(say(texts, item.confirming.action.label), role: .destructive) { confirm(item.confirming) }
                        .disabled(running || missing)
                    Button(say(texts, "screens.cancel"), role: .cancel) { confirming = nil }
                }
                .navigationTitle(say(texts, item.confirming.action.confirm ?? item.confirming.action.label))
            }
        }
    }

    struct Item: Identifiable {
        let confirming: Confirming
        var id: String { confirming.action.label }
    }
}

extension View {
    /// Asks an action's confirmation before it runs.
    func confirming(_ confirming: Binding<Confirming?>, reason: Binding<String>, texts: Texts, running: Bool, confirm: @escaping (Confirming) -> Void) -> some View {
        modifier(ConfirmDialog(confirming: confirming, reason: reason, texts: texts, running: running, confirm: confirm))
    }
}

extension Service {
    /// The {parameters} of a path, in order.
    public static func parameterNames(_ path: String) -> [String] {
        var out: [String] = []
        var rest = path[...]
        while let open = rest.firstIndex(of: "{"), let close = rest[open...].firstIndex(of: "}") {
            out.append(String(rest[rest.index(after: open)..<close]))
            rest = rest[rest.index(after: close)...]
        }
        return out
    }
}
